<?php
declare(strict_types=1);
function trade_root(): string { return data_root().'/private-domain/trade'; }
function trade_account_file(): string { return trade_root().'/accounts.json'; }
function trade_project_file(): string { return trade_root().'/projects.json'; }
function trade_ensure_dirs(): void { if(!is_dir(trade_root()))@mkdir(trade_root(),0750,true); }
function trade_accounts(): array { trade_ensure_dirs();try{return confidential_json_read(trade_account_file(),'atelierwood:trade-accounts:v1',[]);}catch(Throwable){return[];} }
function trade_projects(): array { trade_ensure_dirs();try{return confidential_json_read(trade_project_file(),'atelierwood:trade-projects:v1',[]);}catch(Throwable){return[];} }
function trade_account_for_customer(?string $customerGuid=null): ?array { $customerGuid=$customerGuid?:((string)(customer_identity()['guid']??''));foreach(trade_accounts() as $a)if(($a['customer_guid']??'')===$customerGuid)return$a;return null; }
function trade_apply(array $src): array { require_customer('/trade/apply');$cg=(string)customer_identity()['guid'];$existing=trade_account_for_customer($cg);if($existing)return$existing;$company=trim((string)($src['company']??''));$role=trim((string)($src['role']??''));$gstin=strtoupper(trim((string)($src['gstin']??'')));if(text_len($company)<2||text_len($role)<2)throw new RuntimeException('Company/studio and professional role are required.');$a=['guid'=>uuidv7(),'customer_guid'=>$cg,'company'=>$company,'role'=>$role,'gstin'=>$gstin,'website'=>trim((string)($src['website']??'')),'status'=>'PENDING','discount_percent'=>0,'notes'=>'','created_at'=>gmdate('c'),'updated_at'=>gmdate('c')];$rows=trade_accounts();$rows[]=$a;confidential_json_write(trade_account_file(),$rows,'atelierwood:trade-accounts:v1',foundation_checksum(trade_account_file()));audit_event('trade.apply',['account_guid'=>$a['guid'],'customer_guid'=>$cg]);return$a; }
function trade_admin_decide(string $guid,string $status,int $discount,string $notes=''): array { require_admin();$status=strtoupper($status);if(!in_array($status,['APPROVED','REJECTED','PENDING'],true))throw new RuntimeException('Invalid trade status.');$discount=max(0,min(25,$discount));$updated=null;$rows=trade_accounts();foreach($rows as &$a)if(($a['guid']??'')===$guid){$a['status']=$status;$a['discount_percent']=$status==='APPROVED'?$discount:0;$a['notes']=trim($notes);$a['updated_at']=gmdate('c');$updated=$a;break;}unset($a);if(!$updated)throw new RuntimeException('Trade account not found.');confidential_json_write(trade_account_file(),$rows,'atelierwood:trade-accounts:v1',foundation_checksum(trade_account_file()));audit_event('trade.decision',['account_guid'=>$guid,'status'=>$status,'discount'=>$updated['discount_percent']]);return$updated; }
function trade_require_approved(): array { require_customer('/trade');$a=trade_account_for_customer();if(!$a||($a['status']??'')!=='APPROVED')throw new RuntimeException('Approved TradeOS account required.');return$a; }
function trade_customer_projects(?string $customerGuid=null): array { $customerGuid=$customerGuid?:((string)(customer_identity()['guid']??''));$rows=array_values(array_filter(trade_projects(),fn($p)=>($p['customer_guid']??'')===$customerGuid));usort($rows,fn($a,$b)=>strcmp((string)($b['updated_at']??''),(string)($a['updated_at']??'')));return$rows; }
function trade_customer_project(string $guid,?string $customerGuid=null): ?array { $customerGuid=$customerGuid?:((string)(customer_identity()['guid']??''));foreach(trade_projects() as $p)if(($p['guid']??'')===$guid&&($p['customer_guid']??'')===$customerGuid)return$p;return null; }
function trade_create_project(array $src): array { $account=trade_require_approved();$name=trim((string)($src['name']??''));$client=trim((string)($src['client']??''));if(text_len($name)<2)throw new RuntimeException('Project name is required.');$p=['guid'=>uuidv7(),'number'=>'AWT-'.strtoupper(substr(bin2hex(random_bytes(4)),0,8)),'customer_guid'=>$account['customer_guid'],'trade_account_guid'=>$account['guid'],'name'=>$name,'client'=>$client,'location'=>trim((string)($src['location']??'')),'status'=>'ACTIVE','lines'=>[],'created_at'=>gmdate('c'),'updated_at'=>gmdate('c')];$rows=trade_projects();$rows[]=$p;confidential_json_write(trade_project_file(),$rows,'atelierwood:trade-projects:v1',foundation_checksum(trade_project_file()));audit_event('trade.project.create',['project_guid'=>$p['guid']]);return$p; }
function trade_price(array $product,array $account): int { return max(1,(int)round((int)$product['price']*(1-(int)($account['discount_percent']??0)/100))); }
function trade_add_line(string $projectGuid,string $slug,int $qty,string $notes=''): array { $account=trade_require_approved();$project=trade_customer_project($projectGuid);if(!$project)throw new RuntimeException('Project not found.');$product=product_by_slug($slug);if(!$product)throw new RuntimeException('Product not found.');$qty=max(1,min(99,$qty));$line=['guid'=>uuidv7(),'product_guid'=>$product['guid'],'slug'=>$product['slug'],'sku'=>$product['sku'],'name'=>$product['name'],'qty'=>$qty,'list_price'=>(int)$product['price'],'trade_unit_price'=>trade_price($product,$account),'notes'=>trim($notes),'added_at'=>gmdate('c')];$rows=trade_projects();$updated=null;foreach($rows as &$p)if(($p['guid']??'')===$projectGuid&&($p['customer_guid']??'')===$account['customer_guid']){$p['lines'][]=$line;$p['updated_at']=gmdate('c');$updated=$p;break;}unset($p);if(!$updated)throw new RuntimeException('Project not found.');confidential_json_write(trade_project_file(),$rows,'atelierwood:trade-projects:v1',foundation_checksum(trade_project_file()));audit_event('trade.project.line_add',['project_guid'=>$projectGuid,'product_guid'=>$product['guid']]);return$updated; }
function trade_project_totals(array $project): array { $list=0;$trade=0;foreach($project['lines']??[] as $l){$list+=(int)$l['list_price']*(int)$l['qty'];$trade+=(int)$l['trade_unit_price']*(int)$l['qty'];}return['list'=>$list,'trade'=>$trade,'saving'=>$list-$trade]; }
function trade_export_csv(array $project): string { $fh=fopen('php://temp','r+');fputcsv($fh,['SKU','Product','Qty','List Price','Trade Unit','Line Total','Notes']);foreach($project['lines']??[] as $l)fputcsv($fh,[$l['sku'],$l['name'],$l['qty'],$l['list_price'],$l['trade_unit_price'],$l['trade_unit_price']*$l['qty'],$l['notes']]);rewind($fh);$csv=stream_get_contents($fh);fclose($fh);return(string)$csv; }
function trade_release_checks(): array { $accounts=trade_accounts();$projects=trade_projects();$customers=array_column(customer_users(),'guid');$owners=true;$refs=true;$numbers=[];foreach($accounts as $a)if(!in_array($a['customer_guid']??'',$customers,true))$owners=false;foreach($projects as $p){$numbers[]=$p['number']??'';if(!in_array($p['customer_guid']??'',$customers,true))$owners=false;foreach($p['lines']??[] as $l)if(!product_by_guid((string)($l['product_guid']??'')))$refs=false;}return [
 ['name'=>'TradeOS encryption','ok'=>confidential_key()!==null&&confidential_crypto_available(),'detail'=>'Trade accounts, clients and project BOQs use encrypted private persistence.'],
 ['name'=>'TradeOS owner integrity','ok'=>$owners,'detail'=>$owners?'Trade accounts/projects resolve to known customers.':'Orphan TradeOS owner detected.'],
 ['name'=>'TradeOS project number uniqueness','ok'=>count($numbers)===count(array_unique($numbers)),'detail'=>'Trade project numbers are unique.'],
 ['name'=>'TradeOS product references','ok'=>$refs,'detail'=>$refs?'BOQ lines resolve to canonical products.':'Missing catalogue reference in a TradeOS project.'],
 ['name'=>'TradeOS discount boundary','ok'=>!array_filter($accounts,fn($a)=>(int)($a['discount_percent']??0)<0||(int)($a['discount_percent']??0)>25),'detail'=>'Trade discounts remain within the configured 0–25% staging policy.'],
]; }
